mapper.delete:
delete from t_flight_code
where arcr_regn = #{arcrRegn,jdbcType=VARCHAR}
  and arcr_start_date = #{arcrStartDate,jdbcType=DATE}

mapper.update:
update t_flight_code
set arcr_acname = #{arcrAcname,jdbcType=VARCHAR},
  arcr_custom_num = #{arcrCustomNum,jdbcType=VARCHAR},
  arcr_end_date = #{arcrEndDate,jdbcType=DATE}
where arcr_regn = #{arcrRegn,jdbcType=VARCHAR}
  and arcr_start_date = #{arcrStartDate,jdbcType=DATE}

mapper.select:
select arcr_regn, arcr_start_date, arcr_acname, arcr_custom_num, arcr_end_date
from t_flight_code
where arcr_regn = #{arcrRegn,jdbcType=VARCHAR}
  and arcr_start_date = #{arcrStartDate,jdbcType=DATE}
